     3	import com.fasterxml.jackson.databind.ObjectMapper;
     4	import com.fasterxml.jackson.databind.SerializationFeature;
     5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
     6	import com.pousadamarealta.domain.ReportService;
     7	import com.pousadamarealta.domain.ReservationService;
     8	import com.pousadamarealta.messaging.MessageService;
     9	import com.pousadamarealta.repository.ReservationRepository;
    10	import com.pousadamarealta.repository.RoomRepository;
    11	import com.pousadamarealta.web.HotelController;
    12	import io.javalin.Javalin;
    13	import io.javalin.json.JavalinJackson;
    14	
    15	public class Main {
    16	    public static void main(String[] args) {
    17	        // Verificar modo de teste
    18	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
    19	
    20	        // Determinar porta
    21	        int port = 7070;
    22	        String portEnv = System.getenv("PORT");
    23	        if (portEnv != null && !portEnv.isEmpty()) {
    24	            try {
    25	                port = Integer.parseInt(portEnv);
    26	            } catch (NumberFormatException e) {
    27	                System.err.println("Invalid PORT environment variable: " + portEnv);
    28	            }
    29	        }
    30	
    31	        // Configurar Jackson
    32	        ObjectMapper objectMapper = new ObjectMapper();
    33	        objectMapper.registerModule(new JavaTimeModule());
    34	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    35	
    36	        // Inicializar repositórios e serviços
    37	        RoomRepository roomRepository = new RoomRepository();
    38	        ReservationRepository reservationRepository = new ReservationRepository();
    39	        MessageService messageService = new MessageService(testMode);
    40	        ReservationService reservationService = new ReservationService(
    41	                reservationRepository, roomRepository, messageService);
    42	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
    43	
    44	        HotelController controller = new HotelController(
    45	                roomRepository, reservationRepository, reservationService, messageService, reportService);
    46	
    47	        // Criar aplicação Javalin
    48	        Javalin app = Javalin.create(config -> {
    49	            config.jsonMapper(new JavalinJackson(objectMapper, false));
    50	        }).start(port);
    51	
    52	        // Registrar rotas
    53	        app.get("/rooms", controller::getRooms);
    54	        app.post("/reservations", controller::createReservation);
    55	        app.get("/reservations/{id}", controller::getReservation);
    56	        app.post("/reservations/{id}/confirmation", controller::confirmReservation);
    57	        app.post("/reservations/{id}/cancellation", controller::cancelReservation);
    58	        app.post("/reservations/{id}/check-in", controller::checkIn);
    59	        app.post("/reservations/{id}/check-out", controller::checkOut);
    60	        app.get("/reservations/{id}/document", controller::getDocument);
    61	        app.get("/messages", controller::getMessages);
    62	        app.get("/reports/occupancy", controller::getOccupancyReport);
    63	        app.get("/reports/revenue", controller::getRevenueReport);
    64	
    65	        System.out.println("Hotel Reservation System started on port " + port);
    66	        System.out.println("Test mode: " + testMode);
    67	    }
    68	}
