     1	package com.pousadamarealta.messaging;
     2	
     3	import java.util.List;
     4	import java.util.concurrent.atomic.AtomicLong;
     5	
     6	public class ArchiveCopyHandler implements MessageHandler {
     7	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
     8	    private final boolean testMode;
     9	    private final AtomicLong idGenerator;
    10	
    11	    public ArchiveCopyHandler(boolean testMode, AtomicLong idGenerator) {
    12	        this.testMode = testMode;
    13	        this.idGenerator = idGenerator;
    14	    }
    15	
    16	    @Override
    17	    public void handle(OutgoingMessage message, List<Message> sentMessages) {
    18	        // Não criar cópia em modo de teste nem para mensagens bloqueadas
    19	        if (testMode || message.isBlocked()) {
    20	            return;
    21	        }
    22	
    23	        // Criar cópia para o arquivo
    24	        Message archiveCopy = new Message(
    25	                idGenerator.incrementAndGet(),
    26	                MessageChannel.EMAIL,
    27	                ARCHIVE_EMAIL,
    28	                "[Cópia] " + message.getSubject(),
    29	                message.getBody(),
    30	                MessageStatus.SENT
    31	        );
    32	
    33	        sentMessages.add(archiveCopy);
    34	    }
    35	}
=== messaging/EmailValidationHandler.java
     1	package com.pousadamarealta.messaging;
     2	
     3	import java.util.List;
     4	import java.util.regex.Pattern;
     5	
     6	public class EmailValidationHandler implements MessageHandler {
     7	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@]+@[^@]+\\.[^@.]+.*$");
     8	
     9	    @Override
    10	    public void handle(OutgoingMessage message, List<Message> sentMessages) {
    11	        if (!isValidEmail(message.getTo())) {
    12	            message.setBlocked(true);
    13	        }
    14	    }
    15	
    16	    private boolean isValidEmail(String email) {
    17	        if (email == null || email.trim().isEmpty()) {
    18	            return false;
    19	        }
    20	
    21	        String trimmed = email.trim();
    22	        long atCount = trimmed.chars().filter(ch -> ch == '@').count();
    23	        if (atCount != 1) {
    24	            return false;
    25	        }
    26	
    27	        int atIndex = trimmed.indexOf('@');
    28	        if (atIndex == 0) {
    29	            return false;
    30	        }
    31	
    32	        String afterAt = trimmed.substring(atIndex + 1);
    33	        if (afterAt.isEmpty() || !afterAt.contains(".")) {
    34	            return false;
    35	        }
    36	
    37	        return EMAIL_PATTERN.matcher(trimmed).matches();
    38	    }
    39	}
