     1	package com.pousadamarealta.messaging;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	import java.util.concurrent.atomic.AtomicLong;
     6	
     7	public class MessageService {
     8	    private final List<Message> sentMessages;
     9	    private final AtomicLong idGenerator;
    10	    private final List<MessageHandler> handlers;
    11	
    12	    public MessageService(boolean testMode) {
    13	        this.sentMessages = new ArrayList<>();
    14	        this.idGenerator = new AtomicLong(0);
    15	
    16	        // Montar a cadeia de handlers
    17	        this.handlers = new ArrayList<>();
    18	        this.handlers.add(new EmailValidationHandler());
    19	        this.handlers.add(new TestModeHandler(testMode));
    20	        this.handlers.add(new ArchiveCopyHandler(testMode, idGenerator));
    21	    }
    22	
    23	    public void send(String to, String subject, String body) {
    24	        OutgoingMessage outgoing = new OutgoingMessage(to, subject, body);
    25	        List<Message> additionalMessages = new ArrayList<>();
    26	
    27	        // Processar através da cadeia de handlers (exceto ArchiveCopyHandler)
    28	        for (int i = 0; i < handlers.size() - 1; i++) {
    29	            handlers.get(i).handle(outgoing, sentMessages);
    30	        }
    31	
    32	        // Criar a mensagem final
    33	        MessageStatus status = outgoing.isBlocked() ? MessageStatus.BLOCKED : MessageStatus.SENT;
    34	        Message message = new Message(
    35	                idGenerator.incrementAndGet(),
    36	                MessageChannel.EMAIL,
    37	                outgoing.getTo(),
    38	                outgoing.getSubject(),
    39	                outgoing.getBody(),
    40	                status
    41	        );
    42	
    43	        sentMessages.add(message);
    44	
    45	        // Processar o ArchiveCopyHandler por último (depois de adicionar a mensagem original)
    46	        handlers.get(handlers.size() - 1).handle(outgoing, sentMessages);
    47	    }
    48	
    49	    public List<Message> getSentMessages() {
    50	        return new ArrayList<>(sentMessages);
    51	    }
    52	}
