    16	            String originalRecipient = message.getTo();
    17	            message.setTo(TEST_EMAIL);
    18	            message.setSubject("[TESTE] " + message.getSubject());
    19	            message.setBody("Destinatário original: " + originalRecipient + "\n" + message.getBody());
    20	        }
    21	    }
    22	}

