     6	public class SeasonCalculator {
     7	    private static final double HIGH_SEASON_MULTIPLIER = 1.20;
     8	
     9	    public static boolean isHighSeason(LocalDate date) {
    10	        Month month = date.getMonth();
    11	        int day = date.getDayOfMonth();
    12	
    13	        // Julho inteiro
    14	        if (month == Month.JULY) {
    15	            return true;
    16	        }
    17	
    18	        // 15 de dezembro até o fim de fevereiro
    19	        if (month == Month.DECEMBER && day >= 15) {
    20	            return true;
    21	        }
    22	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    23	            return true;
    24	        }
    25	
    26	        return false;
    27	    }
    28	
    29	    public static double getSeasonMultiplier(LocalDate date) {
    30	        return isHighSeason(date) ? HIGH_SEASON_MULTIPLIER : 1.0;
    31	    }
    32	}
