   26	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
   27	                                         LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
   28	        Room room = roomRepository.findByNumber(roomNumber)
   29	                .orElseThrow(() -> new IllegalArgumentException("Room not found"));
   30	
   31	        if (guests > room.getCapacity()) {
   32	            throw new IllegalArgumentException("Capacity exceeded");
   33	        }
   34	
   35	        if (!reservationRepository.isRoomAvailable(roomNumber, checkIn, checkOut, null)) {
   36	            throw new IllegalStateException("Room unavailable");
   37	        }
   38	
   39	        long id = reservationRepository.nextId();
   40	        Reservation reservation = new Reservation(id, roomNumber, guestName, guestEmail, guestCpf,
   41	                checkIn, checkOut, guests, ratePlan);
   42	
   43	        return reservationRepository.save(reservation);
   44	    }
   45	
   46	    public Reservation confirmReservation(long id) {
   47	        Reservation reservation = reservationRepository.findById(id)
   48	                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
   49	
   50	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
   51	                .orElseThrow(() -> new IllegalArgumentException("Room not found"));
   52	
   53	        reservation.confirm(room.getNightlyRate());
   54	
   55	        // Enviar e-mail de confirmação
   56	        sendConfirmationEmail(reservation, room);
   57	
   58	        return reservation;
   59	    }
