   85	    public String generateDocument(Reservation reservation, Room room) {
   86	        NumberFormat currency = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
   87	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
   88	
   89	        StringBuilder doc = new StringBuilder();
   90	        doc.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
   91	        doc.append("Hóspede: ").append(reservation.getGuestName())
   92	                .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
   93	        doc.append("Quarto: ").append(reservation.getRoomNumber())
   94	                .append(" (").append(room.getType().name()).append(")\n");
   95	        doc.append("Entrada: ").append(reservation.getCheckIn().format(dateFormatter))
   96	                .append(" | Saída: ").append(reservation.getCheckOut().format(dateFormatter))
   97	                .append(" | ").append(reservation.getNights())
   98	                .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
   99	
  100	        BigDecimal subtotal = reservation.calculateSubtotal(room.getNightlyRate());
  101	        doc.append("Diárias: ").append(currency.format(subtotal)).append("\n");
  102	
  103	        BigDecimal discount = reservation.calculateDiscount(subtotal);
  104	        if (discount.compareTo(BigDecimal.ZERO) > 0) {
  105	            doc.append("Desconto: ").append(currency.format(discount)).append("\n");
  106	        }
  107	
  108	        BigDecimal total = reservation.calculateTotal(room.getNightlyRate());
  109	        doc.append("Total: ").append(currency.format(total));
  110	
  111	        return doc.toString();
  112	    }
