  114	    private void sendConfirmationEmail(Reservation reservation, Room room) {
  115	        String document = generateDocument(reservation, room);
  116	
  117	        String subject = "Reserva confirmada - Pousada Maré Alta";
  118	        String body = String.format("Olá, %s!\n\n" +
  119	                        "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
  120	                        "%s\n\n" +
  121	                        "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
  122	                        "Até breve!",
  123	                reservation.getGuestName(), document);
  124	
  125	        messageService.send(reservation.getGuestEmail(), subject, body);
  126	    }
