  7	import com.pousadamarealta.repository.RoomRepository;
  8	import io.javalin.http.Context;
  9	import io.javalin.http.HttpStatus;
 10	
 11	import java.time.LocalDate;
 12	import java.time.format.DateTimeParseException;
 13	import java.util.List;
 14	import java.util.regex.Pattern;
 15	
 16	public class HotelController {
 17	    private final RoomRepository roomRepository;
 18	    private final ReservationRepository reservationRepository;
 19	    private final ReservationService reservationService;
 20	    private final MessageService messageService;
 21	    private final ReportService reportService;
 22	
 23	    private static final Pattern DATE_PATTERN = Pattern.compile("^\\d{4}-\\d{2}-\\d{2}$");
 24	    private static final Pattern MONTH_PATTERN = Pattern.compile("^\\d{4}-\\d{2}$");
 25	
 26	    public HotelController(RoomRepository roomRepository,
 27	                           ReservationRepository reservationRepository,
 28	                           ReservationService reservationService,
 29	                           MessageService messageService,
 30	                           ReportService reportService) {
 31	        this.roomRepository = roomRepository;
 32	        this.reservationRepository = reservationRepository;
 33	        this.reservationService = reservationService;
 34	        this.messageService = messageService;
 35	        this.reportService = reportService;
 36	    }
 37	
 38	    public void getRooms(Context ctx) {
 39	        List<RoomResponse> rooms = roomRepository.findAll().stream()
 40	                .map(RoomResponse::new)
 41	                .toList();
 42	        ctx.json(rooms);
 43	    }
 44	
 45	    public void createReservation(Context ctx) {
 46	        try {
 47	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
 48	
 49	            // Validações
 50	            if (request.getGuestName() == null || request.getGuestEmail() == null ||
 51	                    request.getGuestCpf() == null || request.getCheckIn() == null ||
 52	                    request.getCheckOut() == null || request.getRatePlan() == null) {
 53	                ctx.status(HttpStatus.BAD_REQUEST)
 54	                        .json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
 55	                return;
 56	            }
 57	
 58	            if (!DATE_PATTERN.matcher(request.getCheckIn()).matches() ||
 59	                    !DATE_PATTERN.matcher(request.getCheckOut()).matches()) {
 60	                ctx.status(HttpStatus.BAD_REQUEST)
 61	                        .json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
 62	                return;
 63	            }
 64	
 65	            LocalDate checkIn;
 66	            LocalDate checkOut;
 67	            try {
 68	                checkIn = LocalDate.parse(request.getCheckIn());
 69	                checkOut = LocalDate.parse(request.getCheckOut());
