  3	import java.math.BigDecimal;
  4	import java.math.RoundingMode;
  5	import java.time.LocalDate;
  6	import java.time.temporal.ChronoUnit;
  7	
  8	public class Reservation {
  9	    private final long id;
 10	    private final int roomNumber;
 11	    private final String guestName;
 12	    private final String guestEmail;
 13	    private final String guestCpf;
 14	    private final LocalDate checkIn;
 15	    private final LocalDate checkOut;
 16	    private final int guests;
 17	    private final RatePlan ratePlan;
 18	
 19	    private ReservationStatus status;
 20	    private BigDecimal amountPaid;
 21	    private BigDecimal refund;
 22	
 23	    public Reservation(long id, int roomNumber, String guestName, String guestEmail, String guestCpf,
 24	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
 25	        this.id = id;
 26	        this.roomNumber = roomNumber;
 27	        this.guestName = guestName;
 28	        this.guestEmail = guestEmail;
 29	        this.guestCpf = guestCpf;
 30	        this.checkIn = checkIn;
 31	        this.checkOut = checkOut;
 32	        this.guests = guests;
 33	        this.ratePlan = ratePlan;
 34	        this.status = ReservationStatus.PENDING;
 35	        this.amountPaid = BigDecimal.ZERO;
 36	        this.refund = null;
 37	    }
 38	
 39	    public void confirm(BigDecimal nightlyRate) {
 40	        if (status != ReservationStatus.PENDING) {
 41	            throw new IllegalStateException("Only pending reservations can be confirmed");
 42	        }
 43	        this.status = ReservationStatus.CONFIRMED;
 44	        this.amountPaid = calculateTotal(nightlyRate);
 45	    }
 46	
 47	    public void checkIn() {
 48	        if (status != ReservationStatus.CONFIRMED) {
 49	            throw new IllegalStateException("Only confirmed reservations can check in");
 50	        }
 51	        this.status = ReservationStatus.CHECKED_IN;
 52	    }
 53	
 54	    public void checkOut() {
 55	        if (status != ReservationStatus.CHECKED_IN) {
 56	            throw new IllegalStateException("Only checked-in reservations can check out");
 57	        }
 58	        this.status = ReservationStatus.CHECKED_OUT;
 59	    }
 60	
 61	    public void cancel() {
 62	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
 63	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
 64	        }
 65	
 66	        this.status = ReservationStatus.CANCELLED;
 67	
 68	        // Calcular reembolso
 69	        if (ratePlan == RatePlan.STANDARD) {
 70	            this.refund = amountPaid;
 71	        } else {
 72	            this.refund = BigDecimal.ZERO;
 73	        }
 74	    }
 75	
 76	    public int getNights() {
 77	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
 78	    }
 79	
 80	    public BigDecimal calculateSubtotal(BigDecimal baseNightlyRate) {
 81	        BigDecimal subtotal = BigDecimal.ZERO;
 82	
 83	        LocalDate date = checkIn;
 84	        while (date.isBefore(checkOut)) {
 85	            double multiplier = SeasonCalculator.getSeasonMultiplier(date);
 86	            BigDecimal nightPrice = baseNightlyRate.multiply(BigDecimal.valueOf(multiplier))
 87	                    .setScale(2, RoundingMode.HALF_EVEN);
 88	            subtotal = subtotal.add(nightPrice);
 89	            date = date.plusDays(1);
 90	        }
 91	
 92	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
 93	    }
 94	
 95	    public BigDecimal calculateDiscount(BigDecimal subtotal) {
 96	        if (ratePlan.getDiscountRate().compareTo(BigDecimal.ZERO) == 0) {
 97	            return BigDecimal.ZERO;
 98	        }
 99	
100	        return subtotal.multiply(ratePlan.getDiscountRate())
101	                .setScale(2, RoundingMode.HALF_EVEN);
102	    }
103	
104	    public BigDecimal calculateTotal(BigDecimal baseNightlyRate) {
105	        BigDecimal subtotal = calculateSubtotal(baseNightlyRate);
106	        BigDecimal discount = calculateDiscount(subtotal);
107	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
108	    }
