160	import java.time.LocalDate;
161	import java.time.Month;
162	
163	public class SeasonCalculator {
164	    private static final double HIGH_SEASON_MULTIPLIER = 1.20;
165	
166	    public static boolean isHighSeason(LocalDate date) {
167	        Month month = date.getMonth();
168	        int day = date.getDayOfMonth();
169	
170	        // Julho inteiro
171	        if (month == Month.JULY) {
172	            return true;
173	        }
174	
175	        // 15 de dezembro até o fim de fevereiro
176	        if (month == Month.DECEMBER && day >= 15) {
177	            return true;
178	        }
179	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
180	            return true;
181	        }
182	
183	        return false;
184	    }
185	
186	    public static double getSeasonMultiplier(LocalDate date) {
187	        return isHighSeason(date) ? HIGH_SEASON_MULTIPLIER : 1.0;
188	    }
