135	        return checkOut;
136	    }
137	
138	    public int getGuests() {
139	        return guests;
140	    }
141	
142	    public RatePlan getRatePlan() {
143	        return ratePlan;
144	    }
145	
146	    public ReservationStatus getStatus() {
147	        return status;
148	    }
149	
150	    public BigDecimal getAmountPaid() {
151	        return amountPaid;
152	    }
