    12	public class ReservationRepository {
    13	    private final List<Reservation> reservations;
    14	    private final AtomicLong idGenerator;
    15	
    16	    public ReservationRepository() {
    17	        this.reservations = new ArrayList<>();
    18	        this.idGenerator = new AtomicLong(0);
    19	    }
    20	
    21	    public Reservation save(Reservation reservation) {
    22	        reservations.add(reservation);
    23	        return reservation;
    24	    }
    25	
    26	    public Optional<Reservation> findById(long id) {
    27	        return reservations.stream()
    28	                .filter(r -> r.getId() == id)
    29	                .findFirst();
    30	    }
    31	
    32	    public List<Reservation> findAll() {
    33	        return new ArrayList<>(reservations);
    34	    }
    35	
    36	    public long nextId() {
    37	        return idGenerator.incrementAndGet();
    38	    }
    39	
    40	    public boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeReservationId) {
    41	        return reservations.stream()
    42	                .filter(r -> r.getRoomNumber() == roomNumber)
    43	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
    44	                .filter(r -> excludeReservationId == null || r.getId() != excludeReservationId)
    45	                .noneMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
    46	    }
    47	
    48	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
    49	        return !start1.isAfter(end2.minusDays(1)) && !start2.isAfter(end1.minusDays(1));
    50	    }
    51	
    52	    public List<Reservation> findOccupiedOnDate(LocalDate date) {
    53	        return reservations.stream()
    54	                .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED
    55	                        || r.getStatus() == ReservationStatus.CHECKED_IN
    56	                        || r.getStatus() == ReservationStatus.CHECKED_OUT)
    57	                .filter(r -> !r.getCheckIn().isAfter(date) && r.getCheckOut().isAfter(date))
    58	                .toList();
    59	    }
    60	
    61	    public List<Reservation> findStartingInMonth(int year, int month) {
    62	        return reservations.stream()
    63	                .filter(r -> r.getCheckIn().getYear() == year && r.getCheckIn().getMonthValue() == month)
    64	                .filter(r -> {
    65	                    java.math.BigDecimal revenue = r.getAmountPaid();
    66	                    if (r.getRefund() != null) {
    67	                        revenue = revenue.subtract(r.getRefund());
    68	                    }
    69	                    return revenue.compareTo(java.math.BigDecimal.ZERO) > 0;
    70	                })
    71	                .toList();
    72	    }
    73	}
